181→/**
182→ * Share dialog modal for creating and managing shares.
183→ *
184→ * Allows users to:
185→ * - Paste a recipient's public key and create a share
186→ * - View existing recipients with truncated pubkeys
187→ * - Revoke individual recipients with inline confirm
188→ *
189→ * For folders, traverses all descendants and re-wraps keys.
190→ * For files, wraps the single file key for the recipient.
191→ */
192→export function ShareDialog({
193→  isOpen,
194→  onClose,
195→  item,
196→  folderKey,
197→  ipnsName,
198→  parentFolderId,
199→}: ShareDialogProps) {
200→  const [pubKeyInput, setPubKeyInput] = useState('');
201→  const [error, setError] = useState<string | null>(null);
202→  const [success, setSuccess] = useState<string | null>(null);
203→  const [isSharing, setIsSharing] = useState(false);
204→  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);
205→  const [recipients, setRecipients] = useState<SentShare[]>([]);
206→  const [recipientsLoading, setRecipientsLoading] = useState(false);
207→  const [recipientsFetched, setRecipientsFetched] = useState(false);
208→  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
209→  const [revokingId, setRevokingId] = useState<string | null>(null);
210→
211→  const inputRef = useRef<HTMLInputElement>(null);
212→
213→  // Fetch existing recipients when dialog opens
214→  useEffect(() => {
215→    if (!isOpen) {
216→      // Reset state on close
217→      setPubKeyInput('');
218→      setError(null);
219→      setSuccess(null);
220→      setIsSharing(false);
221→      setProgress(null);
222→      setConfirmRevokeId(null);
223→      setRevokingId(null);
224→      setRecipients([]);
225→      setRecipientsLoading(false);
226→      setRecipientsFetched(false);
227→      return;
228→    }
229→
230→    let cancelled = false;
231→    setRecipientsLoading(true);
232→
233→    sharesControllerGetSentShares()
234→      .then((shares) => {
235→        if (cancelled) return;
236→        // Filter to shares for this specific item (by ipnsName)
237→        const itemShares: SentShare[] = shares
238→          .filter((s) => s.ipnsName === ipnsName)
239→          .map((s) => ({
240→            shareId: s.shareId,
241→            recipientPublicKey: s.recipientPublicKey,
242→            itemType: s.itemType as 'folder' | 'file',
243→            ipnsName: s.ipnsName,
244→            itemName: s.itemName,
245→            createdAt: String(s.createdAt),
246→          }));
247→        setRecipients(itemShares);
248→      })
249→      .catch((err) => {
250→        if (cancelled) return;
251→        console.error('Failed to fetch sent shares:', err);
252→      })
253→      .finally(() => {
254→        if (!cancelled) {
255→          setRecipientsLoading(false);
256→          setRecipientsFetched(true);
257→        }
258→      });
259→
260→    return () => {
261→      cancelled = true;
262→    };
263→  }, [isOpen, ipnsName]);
264→
265→  const handleShare = useCallback(async () => {
266→    setError(null);
267→    setSuccess(null);
268→
269→    const key = pubKeyInput.trim();
270→
271→    // Validate format
272→    if (!isValidPublicKey(key)) {
273→      setError('invalid key format -- expected 0x04 + 128 hex chars');
274→      return;
275→    }
276→
277→    // Prevent sharing root folder
278→    if (parentFolderId === 'root' && item.type === 'folder') {
279→      // Check if item is the root folder itself (the one navigated to at root)
280→      const rootFolder = useFolderStore.getState().folders['root'];
281→      if (rootFolder && item.id === 'root') {
282→        setError('cannot share root folder');
283→        return;
284→      }
285→    }
286→
287→    // Check not sharing with yourself
288→    const vaultKeypair = useAuthStore.getState().vaultKeypair;
289→    if (!vaultKeypair) {
290→      setError('vault keypair not available');
291→      return;
292→    }
293→
294→    const myPubKeyHex = '0x' + bytesToHex(vaultKeypair.publicKey);
295→    if (key.toLowerCase() === myPubKeyHex.toLowerCase()) {
296→      setError('cannot share with yourself');
297→      return;
298→    }
299→
300→    setIsSharing(true);
301→
302→    try {
303→      // Verify recipient is a registered user
304→      await sharesControllerLookupUser({ publicKey: key });
305→    } catch (err: unknown) {
306→      const status = (err as { status?: number }).status;
307→      if (status === 404) {
308→        setError('user not found');
309→      } else {
310→        setError('lookup failed, please try again');
311→      }
312→      setIsSharing(false);
313→      return;
314→    }
315→
316→    try {
317→      const recipientPubKeyBytes = hexToBytes(key.slice(2));
318→      const ownerPrivateKey = vaultKeypair.privateKey;
319→
320→      let encryptedKey: string;
321→      let childKeys: ChildKeyDto[] | undefined;
322→
323→      if (item.type === 'folder') {
324→        const folderEntry = item as FolderEntry;
325→
326→        // For folders shared from a parent, folderKey IS the folder's own key
327→        // (it's the folderKey passed as prop which is the parent's key --
328→        //  but the item is a FolderEntry child that has folderKeyEncrypted)
329→        // We need to use folderKeyEncrypted from the FolderEntry to get the actual folder key.
330→        // Wait -- the folderKey prop is the PARENT folder's key. The item's own key
331→        // is obtained by unwrapping folderKeyEncrypted from the FolderEntry.
332→        // Actually, looking at the plan more carefully:
333→        //   "For folders: folderKey is passed as prop"
334→        // But folderKey is the PARENT's key. For sharing a subfolder, we need the subfolder's key.
335→        // Let's check: if the item is a direct child folder, its folderKeyEncrypted
336→        // is wrapped with the owner's public key (ECIES). We unwrap it to get the folder's own key.
337→
338→        // Unwrap the folder's own key from its encrypted form
339→        const itemFolderKey = await unwrapKey(
340→          hexToBytes(folderEntry.folderKeyEncrypted),
341→          ownerPrivateKey
342→        );
343→
344→        try {
345→          // Wrap the folder key for the recipient
346→          const wrappedForRecipient = await wrapKey(itemFolderKey, recipientPubKeyBytes);
347→          encryptedKey = bytesToHex(wrappedForRecipient);
348→
349→          // Now traverse children and re-wrap descendant keys
350→          // First, resolve folder metadata to get children
351→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
352→          if (resolved) {
353→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
354→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
355→            const encrypted = JSON.parse(encryptedJson);
356→            const metadata = await decryptFolderMetadata(encrypted, itemFolderKey);
357→
358→            setProgress({ current: 0, total: 0 });
359→
360→            childKeys = await collectChildKeys(
361→              metadata.children,
362→              itemFolderKey,
363→              ownerPrivateKey,
364→              recipientPubKeyBytes,
365→              (wrapped) => setProgress({ current: wrapped, total: 0 })
366→            );
367→          }
368→        } finally {
369→          itemFolderKey.fill(0);
370→        }
371→      } else {
372→        // File sharing: wrap parent folder key for recipient (needed to decrypt file metadata),
373→        // and re-wrap the file key as a child key entry
374→        const filePointer = item as FilePointer;
375→
376→        // encryptedKey = parent folder key wrapped for recipient
377→        const wrappedFolderKey = await wrapKey(folderKey, recipientPubKeyBytes);
378→        encryptedKey = bytesToHex(wrappedFolderKey);
379→
380→        // Re-wrap the file key for the recipient and store as child key
381→        const { metadata: fileMeta } = await resolveFileMetadata(
382→          filePointer.fileMetaIpnsName,
383→          folderKey
384→        );
385→        const reWrappedFileKey = await reWrapEncryptedKey(
386→          fileMeta.fileKeyEncrypted,
387→          ownerPrivateKey,
388→          recipientPubKeyBytes
389→        );
390→        childKeys = [
391→          { keyType: 'file' as const, itemId: filePointer.id, encryptedKey: reWrappedFileKey },
392→        ];
393→      }
394→
395→      // Create the share via API
396→      const itemType: CreateShareDtoItemType = item.type === 'folder' ? 'folder' : 'file';
397→      const result = await sharesControllerCreateShare({
398→        recipientPublicKey: key,
399→        itemType,
400→        ipnsName,
401→        itemName: item.name,
402→        encryptedKey,
403→        childKeys: childKeys && childKeys.length > 0 ? childKeys : undefined,
404→      });
405→
406→      // Update local recipients list and global store (for re-wrapping cache)
407→      const newShare = {
408→        shareId: result.shareId,
409→        recipientPublicKey: key,
410→        itemType: item.type as 'folder' | 'file',
411→        ipnsName,
412→        itemName: item.name,
413→        createdAt: new Date().toISOString(),
414→      };
415→      setRecipients((prev) => [...prev, newShare]);
416→      useShareStore.getState().addSentShare(newShare);
417→
418→      setSuccess(`shared with ${truncateKey(key)}`);
419→      setPubKeyInput('');
420→      setProgress(null);
421→    } catch (err) {
422→      console.error('Share creation failed:', err);
423→      const message = err instanceof Error ? err.message : 'share creation failed';
424→      setError(message);
425→    } finally {
426→      setIsSharing(false);
427→      setProgress(null);
428→    }
429→  }, [pubKeyInput, item, folderKey, ipnsName, parentFolderId]);
430→
431→  const handleRevoke = useCallback(async (shareId: string) => {
432→    setRevokingId(shareId);
433→    setConfirmRevokeId(null);
434→    try {
435→      await sharesControllerRevokeShare(shareId);
436→      setRecipients((prev) => prev.filter((r) => r.shareId !== shareId));
437→      useShareStore.getState().removeSentShare(shareId);
438→    } catch (err) {
439→      console.error('Revoke failed:', err);
440→      setError('revoke failed');
441→    } finally {
442→      setRevokingId(null);
443→    }
444→  }, []);
445→
446→  const handleKeyDown = useCallback(
447→    (e: React.KeyboardEvent) => {
448→      if (e.key === 'Enter' && !isSharing) {
449→        handleShare();
450→      }
451→    },
452→    [handleShare, isSharing]
453→  );
454→
455→  const itemDisplayName = item.type === 'folder' ? `${item.name}/` : item.name;
456→  const title = `SHARE: ${itemDisplayName}`;
457→
458→  return (
459→    <Modal open={isOpen} onClose={onClose} title={title}>
460→      <div className="share-dialog">
461→        {/* Input section */}
462→        <div className="share-input-section">
463→          <label className="share-input-label" htmlFor="share-pubkey-input">
464→            {'// paste recipient public key'}
465→          </label>
466→          <div className="share-input-row">
467→            <input
468→              ref={inputRef}
469→              id="share-pubkey-input"
470→              type="text"
471→              className={`share-input${error ? ' share-input--error' : ''}`}
472→              placeholder="0x04..."
473→              value={pubKeyInput}
474→              onChange={(e) => {
475→                setPubKeyInput(e.target.value);
476→                setError(null);
477→                setSuccess(null);
478→              }}
479→              onKeyDown={handleKeyDown}
480→              disabled={isSharing}
481→              autoComplete="off"
482→              spellCheck={false}
483→            />
484→            <button
485→              type="button"
486→              className="share-submit-btn"
487→              onClick={handleShare}
488→              disabled={isSharing || !pubKeyInput.trim()}
489→            >
490→              {isSharing ? '...' : '--share'}
491→            </button>
492→          </div>
493→
494→          {/* Error message */}
495→          {error && (
496→            <div className="share-error" role="alert">
497→              {'> '}
498→              {error}
499→            </div>
500→          )}
501→
502→          {/* Success message */}
503→          {success && (
504→            <div className="share-success" role="status">
505→              {'> '}
506→              {success}
507→            </div>
508→          )}
509→
510→          {/* Progress indicator for folder sharing */}
511→          {progress && (
512→            <div className="share-progress" role="status" aria-live="polite">
513→              {'> '}re-wrapping keys... {progress.current}
514→            </div>
515→          )}
516→        </div>
517→
518→        {/* Recipients section */}
519→        <div className="share-recipients-section">
520→          <div className="share-recipients-header">{'// recipients'}</div>
521→
522→          {recipientsLoading || !recipientsFetched ? (
523→            <div className="share-recipients-loading">loading...</div>
524→          ) : recipients.length === 0 ? (
525→            <div className="share-recipients-empty">no recipients yet</div>
526→          ) : (
527→            <div className="share-recipients-list">
528→              {recipients.map((recipient) => (
529→                <div key={recipient.shareId} className="share-recipient">
530→                  <span className="share-recipient-key">
531→                    {truncateKey(recipient.recipientPublicKey)}
532→                  </span>
533→
534→                  {confirmRevokeId === recipient.shareId ? (
535→                    <div className="share-revoke-confirm">
536→                      <span className="share-revoke-confirm-text">{'confirm?'}</span>
537→                      <button
538→                        type="button"
539→                        className="share-revoke-confirm-btn share-revoke-confirm-btn--yes"
540→                        onClick={() => handleRevoke(recipient.shareId)}
541→                        disabled={revokingId === recipient.shareId}
542→                        aria-label="Confirm revoke"
543→                      >
544→                        {revokingId === recipient.shareId ? '...' : '[y]'}
545→                      </button>
546→                      <button
547→                        type="button"
548→                        className="share-revoke-confirm-btn share-revoke-confirm-btn--no"
549→                        onClick={() => setConfirmRevokeId(null)}
550→                        aria-label="Cancel revoke"
551→                      >
552→                        [n]
553→                      </button>
554→                    </div>
555→                  ) : (
556→                    <button
557→                      type="button"
558→                      className="share-revoke-btn"
559→                      onClick={() => setConfirmRevokeId(recipient.shareId)}
560→                      disabled={revokingId !== null}
561→                      aria-label={`Revoke share for ${truncateKey(recipient.recipientPublicKey)}`}
562→                    >
563→                      --revoke
564→                    </button>
565→                  )}
566→                </div>
567→              ))}
568→            </div>
569→          )}
570→        </div>
571→      </div>
572→    </Modal>
573→  );
574→}
