 17→/**
 18→ * Generate a secp256k1 keypair for testing.
 19→ */
 20→function generateTestKeypair(): { publicKey: Uint8Array; privateKey: Uint8Array } {
 21→  const privateKey = secp256k1.utils.randomPrivateKey();
 22→  const publicKey = secp256k1.getPublicKey(privateKey, false); // uncompressed
 23→  return { publicKey, privateKey };
 24→}
 25→
 26→describe('ECIES Key Wrapping', () => {
 27→  describe('wrapKey / unwrapKey round-trip', () => {
 28→    it('should wrap and unwrap a 32-byte key correctly', async () => {
 29→      const keypair = generateTestKeypair();
 30→      const originalKey = generateFileKey();
 31→
 32→      const wrappedKey = await wrapKey(originalKey, keypair.publicKey);
 33→      const unwrappedKey = await unwrapKey(wrappedKey, keypair.privateKey);
 34→
 35→      expect(unwrappedKey).toEqual(originalKey);
 36→    });
 37→
 38→    it('should handle small data (1 byte)', async () => {
 39→      const keypair = generateTestKeypair();
 40→      const originalData = new Uint8Array([0x42]);
 41→
 42→      const wrapped = await wrapKey(originalData, keypair.publicKey);
 43→      const unwrapped = await unwrapKey(wrapped, keypair.privateKey);
 44→
 45→      expect(unwrapped).toEqual(originalData);
 46→    });
 47→
 48→    it('should handle arbitrary size data', async () => {
 49→      const keypair = generateTestKeypair();
 50→      const originalData = new TextEncoder().encode('This is some arbitrary data for testing');
 51→
 52→      const wrapped = await wrapKey(originalData, keypair.publicKey);
 53→      const unwrapped = await unwrapKey(wrapped, keypair.privateKey);
 54→
 55→      expect(new TextDecoder().decode(unwrapped)).toBe('This is some arbitrary data for testing');
 56→    });
 57→
 58→    it('should produce wrapped output larger than input (includes ephemeral key)', async () => {
 59→      const keypair = generateTestKeypair();
 60→      const originalKey = generateFileKey(); // 32 bytes
 61→
 62→      const wrapped = await wrapKey(originalKey, keypair.publicKey);
 63→
 64→      // ECIES output includes:
 65→      // - 65 bytes ephemeral public key (uncompressed)
 66→      // - Ciphertext (same length as plaintext)
 67→      // - 16 bytes auth tag
 68→      // Total: 65 + 32 + 16 = 113 bytes minimum
 69→      expect(wrapped.length).toBeGreaterThan(originalKey.length);
 70→    });
 71→  });
 72→
 73→  describe('unwrap with wrong private key', () => {
